mapper.select:
SELECT * FROM my_mall.seckill_order
WHERE user_id = #{userId}
ORDER BY create_time DESC

SELECT * FROM my_mall.seckill_order
WHERE order_id = #{orderId}
LIMIT 1

mapper.insert:
INSERT INTO my_mall.seckill_order (
    user_id, seckill_goods_id, order_id, status, create_time, update_time
) VALUES (
             #{userId}, #{seckillGoodsId}, #{orderId}, #{status}, #{createTime}, #{updateTime}
         )

mapper.delete:
DELETE FROM my_mall.seckill_order
WHERE user_id = #{userId} AND seckill_goods_id = #{seckillGoodsId}
  AND order_id = 0
